#!/usr/bin/env node
// typeship — command-line client. Generated by typeship — https://typeship.dev
// Flags-only for API commands (CI-safe); `login` is the one interactive
// exception (hidden prompt on a TTY, --with-token/--token for scripts).
// Prints raw JSON to stdout; errors as JSON on stderr.
// Exit codes: 0 success, 1 API/transport error, 2 usage error.

import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { TypeshipClient, formatDebugEvent, type DebugEvent } from "./index.js";
import { GLOBALS, OPS, buildArgs, findOp, missingRequired, type OpSpec, type ParamSpec } from "./ops.js";


const BIN = "typeship";
const DEFAULT_BASE_URL = "https://typeship.dev/api/v1";
const AUTH_SCALARS: { option: string; flag: string; env: string }[] = [{"option":"bearerToken","flag":"token","env":"TYPESHIP_TOKEN"}];
const BASIC: { envUser: string; envPass: string } | null = null;
const EXCLUDED_OPS = 0;
const VERSION = "1.0.0";
const API_VERSION = "1.0.0";
const WHOAMI: { resource: string; method: string } | null = {"resource":"account","method":"whoami"};
const ENVIRONMENTS: Record<string, string> = {};
const HAS_MCP = true;
const PKG_NAME = "typeship-sdk";
const UPDATE_NOTICE = false;
const API_DESCRIPTION: string | null = "Generate a zero-dependency TypeScript SDK, a CLI, and an MCP server from\nan OpenAPI spec. Generation and shares need no authentication. Projects\nand hosted generations require an API key, created in the console and\nsent as `Authorization: Bearer tsk_...`.\n";
const DOCS_URL_DEFAULT: string | null = "https://typeship.dev";
const RELAY: { mintUrl: string; project: string } | null = null;
const SUPPORT_URL: string | null = null;
const OAUTH_TOKEN_URL: string | null = null;
const OAUTH_CLIENT_ID: string | null = null;
const OAUTH_SCOPES: string[] = [];
const OAUTH_TOKEN_PARAMS: Record<string, string> = {};

interface Parsed {
  positionals: string[];
  flags: Map<string, string | boolean>;
  help: boolean;
}

/** Global flags that never take a value, so they don't swallow the next
 * positional (`--non-interactive accounts list`). */
const GLOBAL_BOOLEAN_FLAGS = new Set([
  "all", "version", "with-token", "check", "non-interactive",
  "claude", "cursor", "claude-desktop", "web", "debug", "validate",
]);

function parseArgv(argv: string[]): Parsed {
  const positionals: string[] = [];
  const flags = new Map<string, string | boolean>();
  let help = false;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    if (arg === "--help" || arg === "-h") { help = true; continue; }
    if (arg === "-v") { flags.set("version", true); continue; }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      if (eq !== -1) {
        flags.set(arg.slice(2, eq), arg.slice(eq + 1));
      } else if (GLOBAL_BOOLEAN_FLAGS.has(arg.slice(2))) {
        flags.set(arg.slice(2), true);
      } else {
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
          flags.set(arg.slice(2), next);
          i++;
        } else {
          flags.set(arg.slice(2), true);
        }
      }
    } else {
      positionals.push(arg);
    }
  }
  return { positionals, flags, help };
}

function nonInteractive(parsed: Parsed): boolean {
  return parsed.flags.get("non-interactive") === true || process.env["TYPESHIP_NON_INTERACTIVE"] === "1";
}

// ---------------------------------------------------------------------------
// color — human surfaces only (help, stderr hints); JSON is never colored
// ---------------------------------------------------------------------------

let COLOR_OUT = false;
let COLOR_ERR = false;

/** --color on|off|auto (Stripe-style; explicit beats NO_COLOR beats TTY). */
function colorEnabled(stream: { isTTY?: boolean }, parsed: Parsed): boolean {
  const flag = parsed.flags.get("color");
  if (flag === "off" || flag === "never") return false;
  if (flag === "on" || flag === "always") return true;
  if (flag !== undefined && flag !== true && flag !== "auto") {
    fail(2, "--color expects on, off, or auto");
  }
  if (process.env.NO_COLOR !== undefined && process.env.NO_COLOR !== "") return false;
  return stream.isTTY === true && process.env.TERM !== "dumb";
}

const ANSI = { bold: "1", dim: "2", cyan: "36", yellow: "33", green: "32" } as const;

function paintOut(code: keyof typeof ANSI, text: string): string {
  return COLOR_OUT ? "\x1b[" + ANSI[code] + "m" + text + "\x1b[0m" : text;
}

function paintErr(code: keyof typeof ANSI, text: string): string {
  return COLOR_ERR ? "\x1b[" + ANSI[code] + "m" + text + "\x1b[0m" : text;
}

function out(value: unknown): void {
  process.stdout.write(JSON.stringify(value, null, 2) + "\n");
}

/** Thrown after scheduling exit so sync callers stop; main() swallows it. */
class ExitPending extends Error {}

/** Exit only after stdout has flushed — process.exit() mid-write truncates
 * large payloads on pipes. */
function flushExit(code: number): Promise<never> {
  return new Promise(() => {
    process.stdout.write("", () => process.exit(code));
  });
}

function fail(code: number, message: string, extra?: unknown): never {
  const payload = JSON.stringify({ error: message, ...(extra !== undefined ? { detail: extra } : {}) }, null, 2) + "\n";
  process.stderr.write(payload, () => process.exit(code));
  throw new ExitPending();
}

// ---------------------------------------------------------------------------
// credentials — written by `login`, cleared by `logout`
// ---------------------------------------------------------------------------

interface StoredCreds {
  scalars?: Record<string, string>;
  basic?: { username: string; password: string };
  oauth?: { accessToken: string; refreshToken?: string; expiresAt?: number };
}

function configDir(): string {
  const base = process.env.XDG_CONFIG_HOME ?? join(homedir(), ".config");
  return join(base, BIN);
}

function credsPath(): string {
  return join(configDir(), "credentials.json");
}

function readCreds(): StoredCreds | null {
  try {
    return JSON.parse(readFileSync(credsPath(), "utf8")) as StoredCreds;
  } catch {
    return null;
  }
}

function writeCreds(creds: StoredCreds): void {
  mkdirSync(configDir(), { recursive: true, mode: 0o700 });
  writeFileSync(credsPath(), JSON.stringify(creds, null, 2) + "\n", { mode: 0o600 });
}

function readStdin(): Promise<string> {
  return new Promise((resolve) => {
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => { data += chunk; });
    process.stdin.on("end", () => resolve(data));
  });
}

/** Hidden-input prompt. Login is the one interactive command; every API
 * command stays flags-only. */
function promptHidden(promptText: string): Promise<string> {
  return new Promise((resolve) => {
    process.stderr.write(promptText);
    const stdin = process.stdin;
    if (stdin.isTTY) stdin.setRawMode(true);
    stdin.resume();
    stdin.setEncoding("utf8");
    let value = "";
    const onData = (chunk: string) => {
      for (const ch of chunk) {
        if (ch === "\n" || ch === "\r" || ch === "\u0004") {
          if (stdin.isTTY) stdin.setRawMode(false);
          stdin.pause();
          stdin.off("data", onData);
          process.stderr.write("\n");
          resolve(value);
          return;
        }
        if (ch === "\u0003") {
          if (stdin.isTTY) stdin.setRawMode(false);
          process.stderr.write("\n");
          process.exit(2);
        }
        if (ch === "\u007f" || ch === "\b") { value = value.slice(0, -1); continue; }
        value += ch;
      }
    };
    stdin.on("data", onData);
  });
}

async function oauthForm(url: string, params: Record<string, string>): Promise<{ status: number; body: Record<string, unknown> | null }> {
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
    body: new URLSearchParams(params).toString(),
  });
  let body: Record<string, unknown> | null = null;
  try { body = await response.json() as Record<string, unknown>; } catch { /* non-JSON error body */ }
  return { status: response.status, body };
}

/** RFC 8628 device flow: discover the device endpoint from the token URL's
 * well-known metadata, show the code, poll until authorized. */
async function deviceLogin(clientId: string): Promise<void> {
  if (!OAUTH_TOKEN_URL) fail(2, "This API declares no OAuth token URL.");
  const origin = new URL(OAUTH_TOKEN_URL).origin;
  let deviceEndpoint: string | undefined;
  let tokenEndpoint = OAUTH_TOKEN_URL;
  for (const wellKnown of ["/.well-known/oauth-authorization-server", "/.well-known/openid-configuration"]) {
    try {
      const response = await fetch(origin + wellKnown, { headers: { Accept: "application/json" } });
      if (!response.ok) continue;
      const meta = await response.json() as { device_authorization_endpoint?: string; token_endpoint?: string };
      if (meta.device_authorization_endpoint) {
        deviceEndpoint = meta.device_authorization_endpoint;
        if (meta.token_endpoint) tokenEndpoint = meta.token_endpoint;
        break;
      }
    } catch { /* try the next well-known path */ }
  }
  if (!deviceEndpoint) {
    fail(1, "The authorization server does not advertise a device flow. Run '" + BIN + " login' with a pasted credential instead.");
  }
  const start = await oauthForm(deviceEndpoint!, {
    client_id: clientId,
    ...(OAUTH_SCOPES.length > 0 ? { scope: OAUTH_SCOPES.join(" ") } : {}),
    ...OAUTH_TOKEN_PARAMS,
  });
  const startBody = start.body as { device_code?: string; user_code?: string; verification_uri?: string; verification_uri_complete?: string; interval?: number; expires_in?: number } | null;
  if (start.status !== 200 || !startBody?.device_code) {
    fail(1, "Device authorization failed (HTTP " + start.status + ").", start.body);
  }
  const uri = startBody!.verification_uri_complete ?? startBody!.verification_uri;
  process.stderr.write("Open " + paintErr("cyan", String(uri)) + " and enter code: " + paintErr("bold", String(startBody!.user_code)) + "\n");
  let intervalMs = (startBody!.interval ?? 5) * 1000;
  const deadline = Date.now() + (startBody!.expires_in ?? 900) * 1000;
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, intervalMs));
    const poll = await oauthForm(tokenEndpoint, {
      grant_type: "urn:ietf:params:oauth:grant-type:device_code",
      device_code: startBody!.device_code!,
      client_id: clientId,
    });
    const tokenBody = poll.body as { access_token?: string; refresh_token?: string; expires_in?: number; error?: string } | null;
    if (poll.status === 200 && tokenBody?.access_token) {
      writeCreds({
        ...(readCreds() ?? {}),
        oauth: {
          accessToken: tokenBody.access_token,
          refreshToken: tokenBody.refresh_token,
          expiresAt: tokenBody.expires_in ? Date.now() + tokenBody.expires_in * 1000 : undefined,
        },
      });
      process.stderr.write(paintErr("green", "Logged in.") + "\n");
      out({ ok: true, method: "device", credentials: credsPath() });
      await flushExit(0);
    }
    const errorCode = tokenBody?.error;
    if (errorCode === "authorization_pending") continue;
    if (errorCode === "slow_down") { intervalMs += 5000; continue; }
    fail(1, "Device login failed: " + (errorCode ?? "HTTP " + poll.status), poll.body);
  }
  fail(1, "Device login timed out before the code was entered.");
}

/** Stored OAuth access token, refreshed through the token URL when expired.
 * A failed refresh returns the stale token; the API's 401 explains better
 * than a local guess. */
async function refreshedOauthToken(stored: StoredCreds): Promise<string | undefined> {
  const oauth = stored.oauth;
  if (!oauth) return undefined;
  const expired = oauth.expiresAt !== undefined && Date.now() > oauth.expiresAt - 60_000;
  if (!expired || !oauth.refreshToken || !OAUTH_TOKEN_URL) return oauth.accessToken;
  const clientId = process.env["TYPESHIP_CLIENT_ID"] ?? OAUTH_CLIENT_ID;
  const result = await oauthForm(OAUTH_TOKEN_URL, {
    grant_type: "refresh_token",
    refresh_token: oauth.refreshToken,
    ...(clientId ? { client_id: clientId } : {}),
  });
  const body = result.body as { access_token?: string; refresh_token?: string; expires_in?: number } | null;
  if (result.status === 200 && body?.access_token) {
    const next = {
      accessToken: body.access_token,
      refreshToken: body.refresh_token ?? oauth.refreshToken,
      expiresAt: body.expires_in ? Date.now() + body.expires_in * 1000 : undefined,
    };
    writeCreds({ ...stored, oauth: next });
    return next.accessToken;
  }
  return oauth.accessToken;
}

async function storePastedToken(stored: StoredCreds, token: string): Promise<void> {
  const first = AUTH_SCALARS[0];
  if (!first) fail(2, "This API declares no credential the CLI can store. Use --username/--password if it uses basic auth.");
  stored.scalars = { ...stored.scalars, [first!.option]: token };
  writeCreds(stored);
  out({ ok: true, method: "paste", stored_as: first!.flag, credentials: credsPath() });
  await flushExit(0);
}

async function cmdLogin(parsed: Parsed): Promise<void> {
  if (parsed.help) {
    const lines = [
      BIN + " login — store credentials at " + credsPath(),
      "",
      ...AUTH_SCALARS.map((a) => "  " + BIN + " login --" + a.flag + " <value>"),
      "  " + BIN + " login --with-token           read the credential from stdin (CI)",
      ...(OAUTH_TOKEN_URL ? ["  " + BIN + " login --client-id <id>       OAuth device flow" + (OAUTH_CLIENT_ID ? " (a default id is built in)" : "")] : []),
      ...(BASIC ? ["  " + BIN + " login --username <u> --password <p>"] : []),
      "  " + BIN + " login                        interactive prompt (TTY only)",
      "",
      "Precedence at request time: flags > env vars > stored credentials.",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }
  const stored: StoredCreds = readCreds() ?? {};

  const scalarValues: Record<string, string> = {};
  for (const a of AUTH_SCALARS) {
    const v = parsed.flags.get(a.flag);
    if (typeof v === "string") scalarValues[a.option] = v;
  }
  const username = parsed.flags.get("username");
  const password = parsed.flags.get("password");
  const gotBasic = BASIC !== null && typeof username === "string" && typeof password === "string";
  if (Object.keys(scalarValues).length > 0 || gotBasic) {
    if (Object.keys(scalarValues).length > 0) stored.scalars = { ...stored.scalars, ...scalarValues };
    if (gotBasic) stored.basic = { username: username as string, password: password as string };
    writeCreds(stored);
    out({ ok: true, method: "flags", credentials: credsPath() });
    await flushExit(0);
  }

  if (parsed.flags.get("with-token") === true) {
    const token = (await readStdin()).trim();
    if (!token) fail(2, "--with-token expects the credential on stdin.");
    await storePastedToken(stored, token);
  }

  const clientId = (typeof parsed.flags.get("client-id") === "string" ? parsed.flags.get("client-id") as string : undefined)
    ?? process.env["TYPESHIP_CLIENT_ID"] ?? OAUTH_CLIENT_ID ?? undefined;
  if (OAUTH_TOKEN_URL && clientId !== undefined && !nonInteractive(parsed)) {
    await deviceLogin(clientId);
  }

  if (nonInteractive(parsed) || !process.stdin.isTTY) {
    fail(2, "Non-interactive: pass the credential as a flag (see '" + BIN + " login --help') or pipe it with --with-token.");
  }
  const first = AUTH_SCALARS[0];
  if (!first) fail(2, "This API declares no credential the CLI can prompt for. See '" + BIN + " login --help'.");
  const token = (await promptHidden("Paste " + first.flag.replace(/-/g, " ") + " (input hidden): ")).trim();
  if (!token) fail(2, "Nothing entered.");
  await storePastedToken(stored, token);
}

async function cmdLogout(): Promise<void> {
  const existed = existsSync(credsPath());
  rmSync(credsPath(), { force: true });
  out({ ok: true, removed: existed ? credsPath() : null });
  await flushExit(0);
}

async function cmdWhoami(parsed: Parsed): Promise<void> {
  const op = WHOAMI ? OPS.find((o) => o.resource === WHOAMI.resource && o.method === WHOAMI.method) : undefined;
  if (op) {
    const client = await makeClient(parsed.flags);
    const target = (client as unknown as Record<string, Record<string, () => Promise<{ ok: boolean; data?: unknown; error?: unknown }>>>)[op.resource]!;
    const result = await target[op.method]!();
    if (result.ok) { out(result.data ?? { ok: true }); await flushExit(0); }
    fail(1, errorMessage(result.error), serializeError(result.error));
  }
  const stored = readCreds();
  let source = "none";
  if (AUTH_SCALARS.some((a) => typeof parsed.flags.get(a.flag) === "string")) {
    source = "flags";
  } else {
    const envScalar = AUTH_SCALARS.find((a) => process.env[a.env] !== undefined);
    if (envScalar) source = "env:" + envScalar.env;
    else if (stored && (stored.scalars || stored.basic || stored.oauth)) source = "login";
  }
  out({ authenticated: source !== "none", source, credentials: existsSync(credsPath()) ? credsPath() : null });
  await flushExit(source === "none" ? 1 : 0);
}

// ---------------------------------------------------------------------------
// config — stored defaults (base URL / named environment)
// ---------------------------------------------------------------------------

interface CliConfigFile {
  baseUrl?: string;
  environment?: string;
  docsUrl?: string;
}

function configFilePath(): string {
  return join(configDir(), "config.json");
}

function readConfig(): CliConfigFile {
  try {
    return JSON.parse(readFileSync(configFilePath(), "utf8")) as CliConfigFile;
  } catch {
    return {};
  }
}

function writeConfig(config: CliConfigFile): void {
  mkdirSync(configDir(), { recursive: true, mode: 0o700 });
  writeFileSync(configFilePath(), JSON.stringify(config, null, 2) + "\n");
}

const CONFIG_KEYS = ["base-url", "environment", "docs-url"];

function configGet(config: CliConfigFile, key: string): string | undefined {
  return key === "base-url" ? config.baseUrl : key === "environment" ? config.environment : config.docsUrl;
}

async function cmdConfig(parsed: Parsed): Promise<void> {
  const sub = parsed.positionals[1];
  const key = parsed.positionals[2];
  const value = parsed.positionals[3];
  if (parsed.help) {
    const lines = [
      BIN + " config — stored defaults at " + configFilePath(),
      "",
      "  " + BIN + " config list",
      "  " + BIN + " config get  <" + CONFIG_KEYS.join("|") + ">",
      "  " + BIN + " config set  base-url <url>",
      ...(Object.keys(ENVIRONMENTS).length > 0
        ? ["  " + BIN + " config set  environment <" + Object.keys(ENVIRONMENTS).join("|") + ">"]
        : []),
      "  " + BIN + " config set  docs-url <url>       docs site for '" + BIN + " docs'",
      "  " + BIN + " config unset <" + CONFIG_KEYS.join("|") + ">",
      "  " + BIN + " config path",
      "",
      "Base URL resolution: --base-url > env var > config base-url > config environment > spec default.",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }
  if (sub === undefined || sub === "list") {
    const config = readConfig();
    out({
      base_url: config.baseUrl ?? null,
      environment: config.environment ?? null,
      docs_url: config.docsUrl ?? DOCS_URL_DEFAULT,
      environments: Object.keys(ENVIRONMENTS),
      file: existsSync(configFilePath()) ? configFilePath() : null,
    });
    await flushExit(0);
  }
  if (sub === "path") {
    process.stdout.write(configFilePath() + "\n");
    await flushExit(0);
  }
  if (sub === "get" || sub === "set" || sub === "unset") {
    if (key === undefined || !CONFIG_KEYS.includes(key)) {
      fail(2, "config " + sub + " expects one of: " + CONFIG_KEYS.join(", "));
    }
    const config = readConfig();
    if (sub === "get") {
      out({ [key.replace(/-/g, "_")]: configGet(config, key) ?? null });
      await flushExit(0);
    }
    if (sub === "unset") {
      if (key === "base-url") delete config.baseUrl;
      else if (key === "environment") delete config.environment;
      else delete config.docsUrl;
      writeConfig(config);
      out({ ok: true });
      await flushExit(0);
    }
    if (value === undefined) fail(2, "config set " + key + " expects a value");
    if (key === "base-url" || key === "docs-url") {
      try {
        new URL(value!);
      } catch {
        fail(2, key + " must be a valid URL");
      }
      if (key === "base-url") config.baseUrl = value;
      else config.docsUrl = value;
    } else {
      if (!(value! in ENVIRONMENTS)) {
        fail(2, Object.keys(ENVIRONMENTS).length > 0
          ? "environment must be one of: " + Object.keys(ENVIRONMENTS).join(", ")
          : "The spec declares no named environments; use 'config set base-url' instead.");
      }
      config.environment = value;
    }
    writeConfig(config);
    out({ ok: true, [key.replace(/-/g, "_")]: value });
    await flushExit(0);
  }
  fail(2, "Unknown config command: " + String(sub) + ". Use list, get, set, unset, or path.");
}

// ---------------------------------------------------------------------------
// mcp — wire the sibling MCP server into agent clients
// ---------------------------------------------------------------------------

function mcpServerPath(): { path: string; warning: string | null } {
  const self = fileURLToPath(import.meta.url);
  let path = self.replace(/cli\.(js|mjs|cjs)$/, "mcp.$1");
  let warning: string | null = null;
  if (self.endsWith(".ts")) {
    path = self.replace(/([\\/])src([\\/])cli\.ts$/, "$1dist$2mcp.js");
    if (!existsSync(path)) {
      warning = "Build the package first (npm install && npm run build) so " + path + " exists.";
    }
  }
  return { path, warning };
}

function claudeDesktopConfigPath(): string {
  if (process.platform === "darwin") {
    return join(homedir(), "Library", "Application Support", "Claude", "claude_desktop_config.json");
  }
  if (process.platform === "win32") {
    return join(process.env.APPDATA ?? join(homedir(), "AppData", "Roaming"), "Claude", "claude_desktop_config.json");
  }
  return join(process.env.XDG_CONFIG_HOME ?? join(homedir(), ".config"), "Claude", "claude_desktop_config.json");
}

async function cmdMcp(parsed: Parsed): Promise<void> {
  if (parsed.help) {
    const lines = [
      BIN + " mcp — connect this API's MCP server to agent clients",
      "",
      "  " + BIN + " mcp                          print the server entry JSON",
      "  " + BIN + " mcp --claude                 write ./.mcp.json (Claude Code)",
      "  " + BIN + " mcp --cursor                 write ./.cursor/mcp.json",
      "  " + BIN + " mcp --claude-desktop         write the Claude Desktop config",
      "  " + BIN + " mcp --url <https://...>      use a remote MCP endpoint instead of the local server",
      "",
      "The local server reads credentials saved by '" + BIN + " login', or the same auth env vars as the CLI.",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }
  const url = typeof parsed.flags.get("url") === "string" ? parsed.flags.get("url") as string : undefined;
  const warnings: string[] = [];
  let entry: Record<string, unknown>;
  if (url) {
    try {
      new URL(url);
    } catch {
      fail(2, "--url must be a valid URL");
    }
    entry = { type: "http", url };
  } else {
    if (!HAS_MCP) {
      fail(2, "This package was generated without the MCP server target. Regenerate with it, or pass --url for a remote endpoint.");
    }
    const server = mcpServerPath();
    if (server.warning) warnings.push(server.warning);
    entry = { command: "node", args: [server.path] };
  }

  const targets: string[] = [];
  if (parsed.flags.get("claude") === true) targets.push(join(process.cwd(), ".mcp.json"));
  if (parsed.flags.get("cursor") === true) targets.push(join(process.cwd(), ".cursor", "mcp.json"));
  if (parsed.flags.get("claude-desktop") === true) targets.push(claudeDesktopConfigPath());

  if (targets.length === 0) {
    out({
      server: BIN,
      entry,
      ...(warnings.length > 0 ? { warnings } : {}),
      note: "Pass --claude, --cursor, or --claude-desktop to write the client config, or merge the entry under mcpServers." + (url ? "" : " The server reads credentials saved by '" + BIN + " login'."),
    });
    await flushExit(0);
  }
  const written: string[] = [];
  for (const file of targets) {
    let doc: { mcpServers?: Record<string, unknown> } = {};
    try {
      doc = JSON.parse(readFileSync(file, "utf8")) as typeof doc;
    } catch { /* absent or invalid: start fresh */ }
    doc.mcpServers = { ...(doc.mcpServers ?? {}), [BIN]: entry };
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, JSON.stringify(doc, null, 2) + "\n");
    written.push(file);
  }
  out({ ok: true, server: BIN, written, entry, ...(warnings.length > 0 ? { warnings } : {}) });
  await flushExit(0);
}

// ---------------------------------------------------------------------------
// upgrade — explicit self-update via the npm registry
// ---------------------------------------------------------------------------

function semverLess(a: string, b: string): boolean {
  const pa = a.split(/[.+-]/).map(Number);
  const pb = b.split(/[.+-]/).map(Number);
  for (let i = 0; i < 3; i++) {
    const x = pa[i] ?? 0;
    const y = pb[i] ?? 0;
    if (x !== y) return x < y;
  }
  return false;
}

function registryBase(): string {
  return (process.env.npm_config_registry ?? "https://registry.npmjs.org").replace(/\/+$/, "");
}

async function latestVersion(timeoutMs: number): Promise<string | null> {
  try {
    const response = await fetch(registryBase() + "/" + PKG_NAME, {
      headers: { Accept: "application/vnd.npm.install-v1+json" },
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!response.ok) return null;
    const doc = await response.json() as { "dist-tags"?: { latest?: string } };
    return doc["dist-tags"]?.latest ?? null;
  } catch {
    return null;
  }
}

async function cmdUpgrade(parsed: Parsed): Promise<void> {
  if (parsed.help) {
    const lines = [
      BIN + " upgrade — update this CLI from the npm registry",
      "",
      "  " + BIN + " upgrade            install the latest published version (npm install -g)",
      "  " + BIN + " upgrade --check    report current vs latest without installing",
      "",
      "Registry: " + registryBase() + " (honors npm_config_registry).",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }
  const latest = await latestVersion(5000);
  if (latest === null) {
    fail(1, PKG_NAME + " is not on the registry (" + registryBase() + "). This package updates by regeneration from its API spec; get the latest from the API provider.");
  }
  const outdated = semverLess(VERSION, latest!);
  if (parsed.flags.get("check") === true) {
    out({ current: VERSION, latest, outdated, registry: registryBase() });
    await flushExit(0);
  }
  if (!outdated) {
    out({ ok: true, current: VERSION, latest, message: "Already up to date." });
    await flushExit(0);
  }
  process.stderr.write("Upgrading " + PKG_NAME + " " + VERSION + " -> " + latest + "\n");
  const install = spawnSync("npm", ["install", "-g", PKG_NAME + "@" + latest], { stdio: ["ignore", "inherit", "inherit"] });
  if (install.status !== 0) {
    fail(1, "npm install failed (exit " + String(install.status) + "). Try: npm install -g " + PKG_NAME + "@latest");
  }
  out({ ok: true, upgraded: { from: VERSION, to: latest } });
  await flushExit(0);
}

// ---------------------------------------------------------------------------
// completion — shell completion scripts built from the op table
// ---------------------------------------------------------------------------

const TOP_WORDS = ["login", "logout", "whoami", "config", "mcp", "upgrade", "docs", "webhooks", "feedback", "completion", "help", "version"];

function completionScript(): string {
  const fn = "_" + BIN.replace(/-/g, "_") + "_complete";
  const resources = [...new Set(OPS.map((o) => o.command[0]))];
  const globalFlags = "--help --version --non-interactive --color --base-url --data --all" +
    AUTH_SCALARS.map((a) => " --" + a.flag).join("");
  const lines: string[] = [];
  lines.push(fn + "() {");
  lines.push('  local cur="${COMP_WORDS[COMP_CWORD]}"');
  lines.push('  local first="${COMP_WORDS[1]}"');
  lines.push('  local second="${COMP_WORDS[2]}"');
  lines.push('  if [ "$COMP_CWORD" -eq 1 ]; then');
  lines.push('    COMPREPLY=($(compgen -W "' + [...TOP_WORDS, ...resources].join(" ") + '" -- "$cur")); return');
  lines.push("  fi");
  lines.push('  if [ "$COMP_CWORD" -eq 2 ]; then');
  lines.push('    case "$first" in');
  for (const resource of resources) {
    const cmds = OPS.filter((o) => o.command[0] === resource).map((o) => o.command[1]).join(" ");
    lines.push("      " + resource + ') COMPREPLY=($(compgen -W "' + cmds + '" -- "$cur")); return ;;');
  }
  lines.push('      config) COMPREPLY=($(compgen -W "list get set unset path" -- "$cur")); return ;;');
  lines.push('      completion) COMPREPLY=($(compgen -W "bash zsh" -- "$cur")); return ;;');
  lines.push('      docs) COMPREPLY=($(compgen -W "search read ' + resources.join(" ") + '" -- "$cur")); return ;;');
  lines.push("    esac");
  lines.push("  fi");
  lines.push('  case "$first $second" in');
  for (const op of OPS) {
    const flags = op.params.filter((p) => p.kind !== "path").map((p) => "--" + p.flag).join(" ");
    lines.push('    "' + op.command[0] + " " + op.command[1] + '") COMPREPLY=($(compgen -W "' + (flags ? flags + " " : "") + globalFlags + '" -- "$cur")); return ;;');
  }
  lines.push("  esac");
  lines.push('  COMPREPLY=($(compgen -W "' + globalFlags + '" -- "$cur"))');
  lines.push("}");
  lines.push("complete -F " + fn + " " + BIN);
  return lines.join("\n");
}

async function cmdCompletion(parsed: Parsed): Promise<void> {
  const shell = parsed.positionals[1];
  if (parsed.help || shell === undefined) {
    const lines = [
      BIN + " completion <bash|zsh> — print a shell completion script",
      "",
      '  bash: add to ~/.bashrc:   eval "$(' + BIN + ' completion bash)"',
      '  zsh:  add to ~/.zshrc:    eval "$(' + BIN + ' completion zsh)"',
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(parsed.help ? 0 : 2);
  }
  if (shell !== "bash" && shell !== "zsh") fail(2, "completion expects bash or zsh");
  const script = shell === "zsh"
    ? "autoload -U +X bashcompinit && bashcompinit\n" + completionScript()
    : completionScript();
  process.stdout.write(script + "\n");
  await flushExit(0);
}

// ---------------------------------------------------------------------------
// docs — spec reference + the docs site's prose (llms.txt convention)
// ---------------------------------------------------------------------------

function docsSiteUrl(): string | null {
  return readConfig().docsUrl ?? DOCS_URL_DEFAULT;
}

/** Fetch llms.txt / llms-full.txt / a prose page from the docs site,
 * with a 1h cache in the config dir. Explicit command = explicit fetch;
 * nothing here runs unless the user asked for docs. */
async function fetchDocs(pathOrFile: string): Promise<string | null> {
  const base = docsSiteUrl();
  const url = /^https?:\/\//.test(pathOrFile)
    ? pathOrFile
    : base === null
      ? null
      : base.replace(/\/+$/, "") + "/" + pathOrFile.replace(/^\/+/, "");
  if (url === null) return null;
  const cacheFile = join(configDir(), "docs-cache", url.replace(/[^a-zA-Z0-9.]+/g, "_").slice(-120));
  try {
    const stat = statSync(cacheFile);
    if (Date.now() - stat.mtimeMs < 60 * 60 * 1000) return readFileSync(cacheFile, "utf8");
  } catch { /* not cached */ }
  try {
    const response = await fetch(url, {
      headers: { Accept: "text/markdown, text/plain, */*" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) return null;
    const text = await response.text();
    mkdirSync(join(configDir(), "docs-cache"), { recursive: true, mode: 0o700 });
    writeFileSync(cacheFile, text);
    return text;
  } catch {
    try {
      return readFileSync(cacheFile, "utf8");
    } catch {
      return null;
    }
  }
}

function referenceFor(op: OpSpec): string {
  const lines: string[] = [];
  lines.push(paintOut("bold", usageLine(op)));
  if (op.summary) lines.push(op.summary);
  lines.push(op.httpMethod + " " + op.path + (op.paginated ? "  (paginated: --all streams every item)" : ""));
  if (op.description) lines.push("", op.description.trim());
  const groups: [string, ParamSpec[]][] = [
    ["Path arguments", op.params.filter((p) => p.kind === "path")],
    ["Flags", op.params.filter((p) => p.kind !== "path")],
  ];
  for (const [label, params] of groups) {
    if (params.length === 0) continue;
    lines.push("", paintOut("bold", label + ":"));
    for (const p of params) {
      const name = p.kind === "path" ? "<" + p.name + ">" : "--" + p.flag;
      const type = p.enum ? p.enum.join("|") : p.type;
      lines.push("  " + padPaint("cyan", name, 30) + type + (p.required ? " " + paintOut("yellow", "(required)") : ""));
      if (p.description) {
        for (const descLine of p.description.trim().split("\n")) lines.push("      " + descLine);
      }
    }
  }
  return lines.join("\n");
}

function openInBrowser(url: string): void {
  const opener = process.platform === "darwin" ? "open" : process.platform === "win32" ? "cmd" : "xdg-open";
  const args = process.platform === "win32" ? ["/c", "start", "", url] : [url];
  spawnSync(opener, args, { stdio: "ignore" });
}

async function cmdDocs(parsed: Parsed): Promise<void> {
  if (parsed.help) {
    const lines = [
      BIN + " docs — API reference from the spec, plus the docs site's guides",
      "",
      "  " + BIN + " docs                          overview",
      "  " + BIN + " docs <resource> <command>     full operation reference",
      "  " + BIN + " docs search <term>            search reference and guides",
      "  " + BIN + " docs read <page>              print a docs-site page in the terminal",
      "  " + BIN + " docs --web                    open the docs site in a browser",
      "",
      "Guides come from the docs site's llms.txt (set with '" + BIN + " config set docs-url <url>').",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }

  if (parsed.flags.get("web") === true) {
    const base = docsSiteUrl();
    if (base === null) fail(2, "No docs site configured. Run '" + BIN + " config set docs-url <url>'.");
    openInBrowser(base!);
    out({ ok: true, opened: base });
    await flushExit(0);
  }

  const sub = parsed.positionals[1];

  if (sub === "search") {
    const term = parsed.positionals.slice(2).join(" ").toLowerCase();
    if (!term) fail(2, "docs search expects a term");
    const lines: string[] = [];
    const refMatches = OPS.filter((op) =>
      (op.command.join(" ") + " " + op.path + " " + (op.summary ?? "") + " " + (op.description ?? "") + " " +
        op.params.map((p) => p.flag).join(" ")).toLowerCase().includes(term));
    if (refMatches.length > 0) {
      lines.push(paintOut("bold", "Reference:"));
      for (const op of refMatches.slice(0, 15)) {
        lines.push("  " + padPaint("cyan", op.command.join(" "), 34) + (op.summary ?? op.httpMethod + " " + op.path));
      }
    }
    const prose = await fetchDocs("llms-full.txt");
    if (prose !== null) {
      let heading = "";
      const proseMatches: string[] = [];
      for (const line of prose.split("\n")) {
        if (/^#{1,3} /.test(line)) heading = line.replace(/^#+ /, "").trim();
        else if (line.toLowerCase().includes(term) && proseMatches.length < 15) {
          proseMatches.push("  " + padPaint("cyan", heading.slice(0, 32), 34) + line.trim().slice(0, 100));
        }
      }
      if (proseMatches.length > 0) {
        lines.push(...(lines.length > 0 ? [""] : []), paintOut("bold", "Guides:"));
        lines.push(...proseMatches);
      }
    } else if (docsSiteUrl() === null) {
      lines.push(...(lines.length > 0 ? [""] : []), "(no docs site configured for guide search: '" + BIN + " config set docs-url <url>')");
    }
    if (lines.length === 0) lines.push("No matches for: " + term);
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(0);
  }

  if (sub === "read") {
    const page = parsed.positionals[2];
    if (page === undefined) fail(2, "docs read expects a page path or URL");
    let target = page!;
    if (!/^https?:\/\//.test(target)) {
      const index = await fetchDocs("llms.txt");
      const linked = index?.match(/\((https?:[^)]+)\)/g)?.map((m) => m.slice(1, -1)) ?? [];
      const hit = linked.find((u) => u.toLowerCase().includes(target.toLowerCase()));
      if (hit !== undefined) target = hit;
    }
    const text = await fetchDocs(target);
    if (text === null) {
      fail(1, docsSiteUrl() === null
        ? "No docs site configured. Run '" + BIN + " config set docs-url <url>'."
        : "Couldn't fetch that page. Run '" + BIN + " docs' to see the index.");
    }
    process.stdout.write(text! + (text!.endsWith("\n") ? "" : "\n"));
    await flushExit(0);
  }

  if (sub !== undefined) {
    const op = findOp(sub!, parsed.positionals[2] ?? "");
    if (!op) {
      const list = OPS.filter((o) => o.command[0] === sub);
      if (list.length === 0) fail(2, "Unknown docs topic: " + sub + ". Run '" + BIN + " docs' for the overview.");
      const lines = [paintOut("bold", "Commands for " + sub + ":"), ""];
      for (const resourceOp of list) {
        lines.push("  " + padPaint("cyan", resourceOp.command.join(" "), 34) + (resourceOp.summary ?? ""));
      }
      process.stdout.write(lines.join("\n") + "\n");
      await flushExit(0);
    }
    process.stdout.write(referenceFor(op!) + "\n");
    await flushExit(0);
  }

  const lines: string[] = [];
  lines.push(paintOut("bold", "typeship") + " (v" + API_VERSION + ")");
  if (API_DESCRIPTION) lines.push("", API_DESCRIPTION.trim());
  lines.push("", paintOut("bold", "Reference:") + " " + BIN + " docs <resource> <command>");
  const byResource = new Map<string, number>();
  for (const op of OPS) byResource.set(op.command[0], (byResource.get(op.command[0]) ?? 0) + 1);
  for (const [resource, count] of byResource) {
    lines.push("  " + padPaint("cyan", resource, 24) + count + " command" + (count === 1 ? "" : "s"));
  }
  const base = docsSiteUrl();
  lines.push("", paintOut("bold", "Guides:") + " " + (base !== null
    ? base + "  (" + BIN + " docs search <term>, " + BIN + " docs read <page>, " + BIN + " docs --web)"
    : "no docs site configured — '" + BIN + " config set docs-url <url>'"));
  if (base !== null) {
    const index = await fetchDocs("llms.txt");
    if (index === null) {
      lines.push("  (the docs site doesn't publish llms.txt; only --web is available)");
    } else {
      const titles = [...index.matchAll(/^- \[([^\]]+)\]/gm)].map((m) => m[1]).slice(0, 12);
      for (const title of titles) lines.push("  " + title);
    }
  }
  process.stdout.write(lines.join("\n") + "\n");
  await flushExit(0);
}

// ---------------------------------------------------------------------------
// webhooks listen — forward relayed events to a local handler
// ---------------------------------------------------------------------------

interface RelayedEvent {
  seq: number;
  method: string;
  headers: Record<string, string>;
  content_type: string | null;
  body: string;
}

function eventTypeOf(body: string): string | null {
  try {
    const parsed = JSON.parse(body) as Record<string, unknown>;
    for (const key of ["type", "event", "event_type", "eventType", "name"]) {
      if (typeof parsed[key] === "string") return parsed[key] as string;
    }
  } catch { /* not JSON */ }
  return null;
}

async function cmdWebhooksFake(parsed: Parsed): Promise<void> {
  void parsed;
  fail(2, "This API's spec declares no webhooks, so there is nothing to fake.");
}

async function cmdWebhooks(parsed: Parsed): Promise<void> {
  const sub = parsed.positionals[1];
  if (parsed.help || sub === undefined) {
    const lines = [
      BIN + " webhooks — work with this API's webhook events",
      "",
      "  " + BIN + " webhooks listen --forward-to localhost:3000/webhooks",
      "  " + BIN + " webhooks listen --forward-to localhost:3000/hooks --events account.created,account.updated",
      "  " + BIN + " webhooks fake [<event>] [--key whsec_...] [--forward-to <url>]",
      "",
      "listen mints a private relay URL to point the API's webhook settings",
      "at; events replay locally with their original headers, so signature",
      "verification keeps working. No tunnels, no exposed ports.",
      "fake sends (or prints) a signed sample event for local handler testing.",
    ];
    process.stdout.write(lines.join("\n") + "\n");
    await flushExit(parsed.help ? 0 : 2);
  }
  if (sub === "fake") { await cmdWebhooksFake(parsed); }
  if (sub !== "listen") fail(2, "Unknown webhooks command: " + String(sub) + ". Try '" + BIN + " webhooks listen' or '" + BIN + " webhooks fake'.");
  if (!RELAY) {
    fail(2, "The webhook relay isn't enabled for this package. The API provider can enable it in their typeship console; the next regeneration bakes it in.");
  }
  const forwardRaw = parsed.flags.get("forward-to");
  if (typeof forwardRaw !== "string") {
    fail(2, "webhooks listen requires --forward-to <url>, e.g. --forward-to localhost:3000/webhooks");
  }
  const forwardTo = /^https?:\/\//.test(forwardRaw as string) ? forwardRaw as string : "http://" + (forwardRaw as string);
  const eventsRaw = parsed.flags.get("events");
  const eventsFilter = typeof eventsRaw === "string"
    ? eventsRaw.split(",").map((s) => s.trim()).filter(Boolean)
    : null;

  interface MintedSession {
    session_id?: string;
    ingest_url?: string;
    poll_url?: string;
    errors?: { message?: string }[];
  }
  let minted: MintedSession | null = null;
  try {
    const response = await fetch(RELAY!.mintUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({ project: RELAY!.project }),
      signal: AbortSignal.timeout(15_000),
    });
    minted = await response.json().catch(() => null) as MintedSession | null;
    if (!response.ok || typeof minted?.ingest_url !== "string" || typeof minted.poll_url !== "string") {
      const detail = minted?.errors?.[0]?.message ?? "HTTP " + response.status;
      fail(1, "Couldn't start a relay session: " + detail);
    }
  } catch (e) {
    if (e instanceof ExitPending) throw e;
    fail(1, "Couldn't reach the relay: " + (e as Error).message);
  }

  process.stderr.write(paintErr("green", "Ready!") + " Forwarding relayed events to " + forwardTo + "\n");
  process.stderr.write("Point this API's webhook endpoint at: " + paintErr("cyan", minted!.ingest_url!) + " (^C to quit)\n");

  let cursor = 0;
  let pollFailures = 0;
  for (;;) {
    let payload: { events: RelayedEvent[]; next: number };
    try {
      const response = await fetch(minted!.poll_url! + "?after=" + cursor + "&wait=1", {
        headers: { Accept: "application/json" },
        signal: AbortSignal.timeout(30_000),
      });
      if (response.status === 404) fail(1, "The relay session expired. Run '" + BIN + " webhooks listen' again.");
      if (!response.ok) throw new Error("HTTP " + response.status);
      payload = await response.json() as typeof payload;
      pollFailures = 0;
    } catch (e) {
      if (e instanceof ExitPending) throw e;
      pollFailures++;
      if (pollFailures > 5) fail(1, "Lost the relay: " + (e as Error).message);
      await new Promise((resolve) => setTimeout(resolve, 2000 * pollFailures));
      continue;
    }
    for (const event of payload.events) {
      cursor = event.seq;
      const type = eventTypeOf(event.body);
      if (eventsFilter !== null && (type === null || !eventsFilter.includes(type))) continue;
      const started = Date.now();
      try {
        const forwarded = await fetch(forwardTo, {
          method: event.method,
          headers: event.headers,
          body: event.method === "GET" ? undefined : event.body,
          signal: AbortSignal.timeout(30_000),
        });
        process.stderr.write(
          (forwarded.ok ? paintErr("green", String(forwarded.status)) : paintErr("yellow", String(forwarded.status))) +
          "  " + (type ?? event.method) + " [" + event.seq + "] (" + (Date.now() - started) + "ms)\n",
        );
      } catch (e) {
        process.stderr.write(paintErr("yellow", "unreachable") + "  " + (type ?? event.method) + " [" + event.seq + "]: " + (e as Error).message + "\n");
      }
    }
    if (payload.next > cursor) cursor = payload.next;
  }
}

async function cmdFeedback(parsed: Parsed): Promise<void> {
  if (parsed.help) {
    process.stdout.write(BIN + " feedback — open the API provider's issue tracker with environment details prefilled\n");
    await flushExit(0);
  }
  if (!SUPPORT_URL) {
    fail(2, "No support URL is configured for this CLI. The API provider can set one in their typeship console.");
  }
  let target = SUPPORT_URL!;
  if (/github\.com\/[^/]+\/[^/]+\/issues\/new/.test(target)) {
    const bodyLines = [
      "<!-- describe the problem or request above the line -->",
      "",
      "---",
      "- cli: " + BIN + " " + VERSION + " (api " + API_VERSION + ")",
      "- node: " + process.version,
      "- platform: " + process.platform + "/" + process.arch,
    ];
    const sep = target.includes("?") ? "&" : "?";
    target += sep + "title=" + encodeURIComponent("[" + BIN + "] ") + "&body=" + encodeURIComponent(bodyLines.join("\n"));
  }
  process.stderr.write("Opening " + paintErr("cyan", SUPPORT_URL!) + "\n");
  openInBrowser(target);
  out({ ok: true, opened: SUPPORT_URL });
  await flushExit(0);
}

/** Opt-in (console setting) once-a-day upgrade hint. Off by default:
 * generated code phones nobody unless the project owner chose this. The
 * notice reads the previous run's cached answer, so commands never wait
 * on the registry; the cache refreshes at most once a day. */
async function maybeUpdateNotice(commandWord: string | undefined, quiet: boolean): Promise<void> {
  if (!UPDATE_NOTICE || quiet) return;
  if (commandWord === undefined || ["upgrade", "version", "help", "login", "logout"].includes(commandWord)) return;
  const cacheFile = join(configDir(), "update-check.json");
  let cache: { checkedAt?: number; latest?: string } = {};
  try {
    cache = JSON.parse(readFileSync(cacheFile, "utf8")) as typeof cache;
  } catch { /* no cache yet */ }
  if ((cache.checkedAt ?? 0) < Date.now() - 24 * 60 * 60 * 1000) {
    const latest = await latestVersion(1500);
    if (latest !== null) {
      cache = { checkedAt: Date.now(), latest };
      mkdirSync(configDir(), { recursive: true, mode: 0o700 });
      writeFileSync(cacheFile, JSON.stringify(cache) + "\n");
    }
  }
  if (cache.latest !== undefined && semverLess(VERSION, cache.latest)) {
    process.stderr.write(paintErr("yellow", "A newer " + BIN + " is available: " + VERSION + " -> " + cache.latest + ". Run '" + BIN + " upgrade'.") + "\n");
  }
}

function usageLine(op: OpSpec): string {
  const paths = op.params.filter((p) => p.kind === "path").map((p) => "<" + p.name + ">").join(" ");
  return BIN + " " + op.command[0] + " " + op.command[1] + (paths ? " " + paths : "");
}

/** Pad to a column, then paint — escape codes must not count toward width. */
function padPaint(code: keyof typeof ANSI, text: string, width: number): string {
  return paintOut(code, text) + " ".repeat(Math.max(1, width - text.length));
}

function printRoot(): void {
  const byResource = new Map<string, OpSpec[]>();
  for (const op of OPS) {
    const list = byResource.get(op.command[0]) ?? [];
    list.push(op);
    byResource.set(op.command[0], list);
  }
  const lines: string[] = [];
  lines.push(paintOut("bold", BIN) + " — " + "typeship" + " (v" + "1.0.0" + ")");
  lines.push("");
  lines.push(paintOut("bold", "Usage:") + " " + BIN + " <resource> <command> [args] [--flags]");
  lines.push("");
  lines.push(paintOut("bold", "Resources:"));
  for (const [resource, list] of byResource) {
    lines.push("  " + padPaint("cyan", resource, 24) + list.map((o) => o.command[1]).join(", "));
  }
  lines.push("");
  lines.push(paintOut("bold", "Global flags:") + " -v/--version, -h/--help, --debug, --non-interactive, --color on|off|auto, --base-url, --data '<json>', --all (paginated lists), --validate (schema-check bodies)" +
    (AUTH_SCALARS.length > 0 ? ", " + AUTH_SCALARS.map((a) => "--" + a.flag).join(", ") : ""));
  lines.push("Auth env vars: " + [
    ...AUTH_SCALARS.map((a) => a.env),
    ...(BASIC ? [BASIC.envUser, BASIC.envPass] : []),
    "TYPESHIP_BASE_URL",
  ].join(", "));
  lines.push("Account: " + BIN + " login | logout | whoami  (stored at " + credsPath() + ")");
  lines.push("Setup: " + BIN + " config (defaults)" + (HAS_MCP ? " | " + BIN + " mcp (agent clients)" : "") + " | " + BIN + " upgrade | " + BIN + " completion <shell>");
  lines.push("Docs: " + BIN + " docs [<resource> <command> | search <term> | read <page> | --web]");
  if (RELAY) lines.push("Webhooks: " + BIN + " webhooks listen --forward-to <url>  (local event forwarding)");
  if (SUPPORT_URL) lines.push("Feedback: " + BIN + " feedback  (opens the provider's issue tracker)");
  if (EXCLUDED_OPS > 0) {
    lines.push("");
    lines.push("Note: " + EXCLUDED_OPS + " operation(s) with binary/multipart bodies are SDK-only.");
  }
  lines.push("");
  lines.push("Run '" + BIN + " <resource> <command> --help' for flags.");
  process.stdout.write(lines.join("\n") + "\n");
}

function printResource(resource: string): void {
  const list = OPS.filter((o) => o.command[0] === resource);
  const lines: string[] = ["Commands for " + resource + ":", ""];
  for (const op of list) {
    lines.push("  " + usageLine(op).padEnd(56) + (op.summary ?? op.httpMethod + " " + op.path));
  }
  process.stdout.write(lines.join("\n") + "\n");
}

function printOp(op: OpSpec): void {
  const lines: string[] = [];
  lines.push(paintOut("bold", usageLine(op)));
  if (op.summary) lines.push(op.summary);
  lines.push(op.httpMethod + " " + op.path);
  lines.push("");
  const rows = op.params.filter((p) => p.kind !== "path");
  if (rows.length > 0) {
    lines.push(paintOut("bold", "Flags:"));
    for (const p of rows) {
      let type: string = p.type;
      if (p.enum) type = p.enum.join("|");
      lines.push(
        "  " + padPaint("cyan", "--" + p.flag, 30) + type.padEnd(18) +
        (p.required ? paintOut("yellow", "(required)") + " " : "") + (p.description ?? "").split("\n")[0]!.slice(0, 80),
      );
    }
  }
  if (op.hasBody) lines.push("  --data '<json>'" + " ".repeat(15) + "raw JSON body" + (op.bodyStyle === "fields" ? " (merged under field flags)" : ""));
  if (op.select) lines.push("  --select '<selection>'" + " ".repeat(9) + "GraphQL selection set override, e.g. '{ id name }'");
  if (op.paginated) lines.push("  --all" + " ".repeat(25) + "stream every item from every page (NDJSON)");
  process.stdout.write(lines.join("\n") + "\n");
}

function coerce(spec: ParamSpec, raw: string | boolean): unknown {
  if (spec.type === "boolean") {
    if (raw === true || raw === "true") return true;
    if (raw === "false") return false;
    fail(2, "--" + spec.flag + " expects true or false");
  }
  if (raw === true) fail(2, "--" + spec.flag + " needs a value");
  const text = String(raw);
  if (spec.type === "number") {
    const n = Number(text);
    if (!Number.isFinite(n)) fail(2, "--" + spec.flag + " expects a number, got: " + text);
    return n;
  }
  if (spec.type === "json") {
    try {
      return JSON.parse(text);
    } catch {
      return text; // let plain strings through for loosely-typed fields
    }
  }
  if (spec.enum && !spec.enum.includes(text)) {
    fail(2, "--" + spec.flag + " must be one of: " + spec.enum.join(", "));
  }
  return text;
}

async function makeClient(flags: Map<string, string | boolean>): Promise<TypeshipClient> {
  const stored = readCreds();
  const config = readConfig();
  const options: Record<string, unknown> = {};
  const baseUrl = (typeof flags.get("base-url") === "string" ? flags.get("base-url") as string : undefined)
    ?? process.env["TYPESHIP_BASE_URL"]
    ?? config.baseUrl
    ?? (config.environment !== undefined ? ENVIRONMENTS[config.environment] : undefined)
    ?? DEFAULT_BASE_URL ?? undefined;
  if (baseUrl === undefined) fail(2, "No base URL. Pass --base-url, set TYPESHIP_BASE_URL, or run '" + BIN + " config set base-url <url>'.");
  options.baseUrl = baseUrl;
  for (const a of AUTH_SCALARS) {
    const v = (typeof flags.get(a.flag) === "string" ? flags.get(a.flag) as string : undefined)
      ?? process.env[a.env] ?? stored?.scalars?.[a.option];
    if (v !== undefined) options[a.option] = v;
  }
  if (BASIC) {
    const username = (typeof flags.get("username") === "string" ? flags.get("username") as string : undefined)
      ?? process.env[BASIC.envUser] ?? stored?.basic?.username;
    const password = (typeof flags.get("password") === "string" ? flags.get("password") as string : undefined)
      ?? process.env[BASIC.envPass] ?? stored?.basic?.password;
    if (username !== undefined && password !== undefined) options.basicAuth = { username, password };
  }
  if (options.bearerToken === undefined && stored?.oauth) {
    const token = await refreshedOauthToken(stored);
    if (token !== undefined) options.bearerToken = token;
  }
  if (flags.get("debug") === true || process.env["TYPESHIP_DEBUG"] === "1") {
    options.debug = (event: DebugEvent) => process.stderr.write(paintErr("dim", formatDebugEvent(BIN, event)) + "\n");
  }
  if (flags.get("validate") === true) options.validate = true;
  for (const g of GLOBALS) {
    const flagValue = flags.get(g.flag);
    const value = typeof flagValue === "string" ? flagValue : process.env["TYPESHIP_" + g.envSuffix];
    if (value !== undefined) options[g.option] = value;
  }
  return new TypeshipClient(options as never);
}

function editDistance(a: string, b: string): number {
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let diag = prev[0]!;
    prev[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const next = Math.min(prev[j]! + 1, prev[j - 1]! + 1, diag + (a[i - 1] === b[j - 1] ? 0 : 1));
      diag = prev[j]!;
      prev[j] = next;
    }
  }
  return prev[b.length]!;
}

/** Closest candidate within edit distance 2, for did-you-mean hints. */
function didYouMean(input: string, candidates: Iterable<string>): string | undefined {
  let best: string | undefined;
  let bestDistance = 3;
  for (const candidate of candidates) {
    const d = editDistance(input.toLowerCase(), candidate.toLowerCase());
    if (d < bestDistance) { bestDistance = d; best = candidate; }
  }
  return best;
}

const BUILTIN_COMMANDS = ["login", "logout", "whoami", "config", "mcp", "docs", "upgrade", "feedback", "completion", "webhooks", "help", "version"];

async function main(): Promise<void> {
  const argv = process.argv.slice(2);
  const parsed = parseArgv(argv);
  if (parsed.positionals[0] === "help") { parsed.positionals.shift(); parsed.help = true; }
  if (parsed.flags.has("version") || parsed.positionals[0] === "version") {
    process.stdout.write(BIN + " " + VERSION + " (" + "typeship" + " " + API_VERSION + ", generated by typeship)\n");
    await flushExit(0);
  }
  const [resourceCmd, methodCmd] = parsed.positionals;
  COLOR_OUT = colorEnabled(process.stdout, parsed);
  COLOR_ERR = colorEnabled(process.stderr, parsed);
  await maybeUpdateNotice(resourceCmd, nonInteractive(parsed));

  if (resourceCmd === "upgrade") { await cmdUpgrade(parsed); }
  if (resourceCmd === "webhooks") { await cmdWebhooks(parsed); }
  if (resourceCmd === "feedback") { await cmdFeedback(parsed); }
  if (resourceCmd === "docs") { await cmdDocs(parsed); }
  if (resourceCmd === "completion") { await cmdCompletion(parsed); }
  if (resourceCmd === "config") { await cmdConfig(parsed); }
  if (resourceCmd === "mcp") { await cmdMcp(parsed); }
  if (resourceCmd === "login") { await cmdLogin(parsed); }
  if (resourceCmd === "logout") {
    if (parsed.help) { process.stdout.write(BIN + " logout — remove " + credsPath() + "\n"); await flushExit(0); }
    await cmdLogout();
  }
  if (resourceCmd === "whoami") {
    if (parsed.help) {
      process.stdout.write(BIN + " whoami — " + (WHOAMI
        ? "call the API's identity endpoint with the resolved credentials"
        : "report which credentials the CLI would use (no identity endpoint in this API)") + "\n");
      await flushExit(0);
    }
    await cmdWhoami(parsed);
  }

  if (!resourceCmd) { printRoot(); await flushExit(parsed.help ? 0 : 2); }
  const resourceExists = OPS.some((o) => o.command[0] === resourceCmd);
  if (!resourceExists) {
    const suggestion = didYouMean(resourceCmd, [...new Set(OPS.map((o) => o.command[0])), ...BUILTIN_COMMANDS]);
    fail(2, "Unknown command: " + resourceCmd + "."
      + (suggestion ? " Did you mean '" + BIN + " " + suggestion + "'?" : "")
      + " Run '" + BIN + " --help' for commands.");
  }
  if (!methodCmd) { printResource(resourceCmd); await flushExit(parsed.help ? 0 : 2); }

  const op = findOp(resourceCmd, methodCmd);
  if (!op) {
    const suggestion = didYouMean(methodCmd, OPS.filter((o) => o.command[0] === resourceCmd).map((o) => o.command[1]));
    fail(2, "Unknown command: " + resourceCmd + " " + methodCmd + "."
      + (suggestion ? " Did you mean '" + BIN + " " + resourceCmd + " " + suggestion + "'?" : "")
      + " Run '" + BIN + " " + resourceCmd + "' for the list.");
  }
  if (parsed.help) { printOp(op); await flushExit(0); }

  const pathSpecs = op.params.filter((p) => p.kind === "path");
  const pathValues = parsed.positionals.slice(2);
  if (pathValues.length !== pathSpecs.length) {
    fail(2, "Expected " + pathSpecs.length + " argument(s): " + usageLine(op));
  }

  const values: Record<string, unknown> = {};
  pathSpecs.forEach((spec, i) => { values[spec.name] = pathValues[i]; });

  let dataBody: unknown;
  const dataRaw = parsed.flags.get("data");
  if (typeof dataRaw === "string") {
    try { dataBody = JSON.parse(dataRaw); } catch (e) { fail(2, "--data is not valid JSON: " + (e as Error).message); }
  }

  const RESERVED_FLAGS = new Set(["data", "all", "select", "base-url", "username", "password", "with-token", "client-id", "version", "url", "claude", "cursor", "claude-desktop", "non-interactive", "check", "color", "web", "forward-to", "events", "debug", "validate", "key", ...AUTH_SCALARS.map((a) => a.flag), ...GLOBALS.map((g) => g.flag)]);
  for (const spec of op.params) {
    if (spec.kind === "path") continue;
    const raw = parsed.flags.get(spec.flag);
    if (raw !== undefined) values[spec.name] = coerce(spec, raw);
  }
  for (const key of parsed.flags.keys()) {
    if (RESERVED_FLAGS.has(key)) continue;
    if (!op.params.some((p) => p.flag === key)) {
      const suggestion = didYouMean(key, [...op.params.filter((p) => p.kind !== "path").map((p) => p.flag), ...RESERVED_FLAGS]);
      fail(2, "Unknown flag --" + key + "."
        + (suggestion ? " Did you mean --" + suggestion + "?" : "")
        + " Run with --help for flags.");
    }
  }

  const missing = missingRequired(op, values).filter((name) =>
    !(op.bodyStyle === "fields" && dataBody !== undefined && typeof dataBody === "object" && dataBody !== null && name in (dataBody as object)),
  );
  if (missing.length > 0) fail(2, "Missing required: " + missing.map((m) => "--" + (op.params.find((p) => p.name === m)?.flag ?? m)).join(", "));

  const client = await makeClient(parsed.flags);
  const selectValue = typeof parsed.flags.get("select") === "string" ? (parsed.flags.get("select") as string) : undefined;
  const args = buildArgs(op, values, dataBody, selectValue);
  const target = (client as unknown as Record<string, Record<string, (...a: unknown[]) => unknown>>)[op.resource]!;
  const callResult = target[op.method]!(...args);

  if (op.paginated && parsed.flags.get("all") === true) {
    try {
      for await (const item of callResult as AsyncIterable<unknown>) {
        process.stdout.write(JSON.stringify(item) + "\n");
      }
      await flushExit(0);
    } catch (e) {
      fail(1, (e as Error).message ?? "Pagination failed", serializeError(e));
    }
  }

  const result = await (callResult as Promise<{ ok: boolean; data?: unknown; error?: unknown }>);
  if (result.ok) {
    if (op.paginated) {
      const page = result.data as { items: unknown[]; hasNextPage(): boolean };
      out({ items: page.items, hasMore: page.hasNextPage() });
    } else {
      out(result.data ?? { ok: true });
    }
    await flushExit(0);
  }
  fail(1, errorMessage(result.error), serializeError(result.error));
}

function errorMessage(error: unknown): string {
  const base = error instanceof Error ? error.name + ": " + error.message : String(error);
  if (error instanceof Error && error.name === "TransportError") {
    return base + " — check the base URL (--base-url, TYPESHIP_BASE_URL, or '" + BIN + " config base-url') and your network";
  }
  return base;
}

function serializeError(error: unknown): unknown {
  if (error && typeof error === "object" && "violations" in error) {
    return { violations: (error as { violations: unknown }).violations };
  }
  if (error && typeof error === "object" && "status" in error) {
    const e = error as { status: number; body?: unknown };
    return { status: e.status, body: e.body };
  }
  return undefined;
}

main().catch((e) => {
  if (e instanceof ExitPending) return;
  try {
    fail(1, errorMessage(e));
  } catch {
    // exit already scheduled
  }
});
